/*
	Noise Layers #genuary2 #genuary #genuary2502
	Layers upon layers upon layers
	https://openprocessing.org/sketch/2498632
	#generativeart #creativecoding #p5js
*/

const USE_SVG = true;
const NUM = 1;
const MAR = 0.3; // margin for non filled areas
let SZE = 14 * NUM, CLRS;

function setup() {
	createCanvas(500, 800, USE_SVG ? SVG : P2D);
	if (!USE_SVG) describe(NUM + " Layer(s) of noise fields");	
	frameRate(30);

	CLRS = []
	for (let i = 0; i < NUM; i++) {
		CLRS[i] = lerpColor(color("steelblue"), color("gold"), random());
	}
	CLRS[NUM-1] = lerpColor(color("darkred"), color("darkorange"), random());

	strokeWeight(2);
	noiseSeed(~~random(999999));
	// noLoop() removed for animation
}

function draw() {
	// if (!USE_SVG) background(2, 2, 12);

	for (let i = 0; i < NUM; i++) {
		stroke(32); // stroke(USE_SVG ? 32 : CLRS[i]);
		drawLayer(SZE/(NUM-i+1)); // reverse order to draw smallest first
	}
}

function drawLayer(SZE) {
	let grid = [];
	const numY = ceil(height/SZE);
	const numX = ceil(width/SZE);

	for (let y = 0, j = 0; y < height; y += SZE, j++) {
		grid[j] = [];
		for (let x = 0, i = 0; x < width; x += SZE, i++) {
			const n = noise(SZE + x/SZE/12, SZE + y/SZE/12, frameCount/231);
			grid[j][i] = 0;
			if (n < MAR) {
				// nothing
			} else if (n < 0.5) {
				grid[j][i] = 1; // horiz
				// line(x, y+SZE, x+SZE, y+SZE); // line(x, y+SZE/2, x+SZE, y+SZE/2);
			} else if (n < 1 - MAR) {
				grid[j][i] = 2; // vert
				// line(x+SZE, y, x+SZE, y+SZE); // line(x+SZE/2, y, x+SZE/2, y+SZE);
			} else {
				// notinhg
			}
		}
	}
	// console.log(grid);

	// combine lines
	let numLines = 0;
	for (let j = 0; j < numY; j++) {
		for (let i = 0; i < numX; i++) {
			if (grid[j][i] === 0) continue;
			let currDir = grid[j][i], curX = i, curY = j;
			if (currDir === 1) {
				// horiz
				while(curX < numX && grid[j][curX] == currDir) {
					grid[j][curX] = 0;
					curX++;
					// console.log(`__ ${curX}/${numX} ${grid[j][curX]}/${grid[j][i]}`);
					// if (grid[j][curX] != currDir) break;
				}
				// console.log(`x: ${i} - ${curX}, y: ${j} : '-' (${(curX-i)})`)
				line(i*SZE, j*SZE+SZE, curX*SZE, curY*SZE+SZE);

			} else {
				// vert
				while(curY < numY && grid[curY][i] == currDir) {
					grid[curY][i] = 0;
					curY++;
					// console.log(`__ ${curY}/${numY} ${grid[curY][i]}/${grid[j][i]}`);
					// if (grid[curY][i] != currDir) break;
				}
				// console.log(`x: ${i}, y: ${j} - ${curY} : '|' (${(curY-j)})`)
				line(i*SZE+SZE, j*SZE, i*SZE+SZE, curY*SZE);

			}
			numLines++;
		}		
	}
	console.log(`numLines: ${numLines}`)
	// console.log(grid)
}

function mouseClicked() {
	if (mouseButton === LEFT) {
		setup();
	}
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("epi_noise_field.svg"); // Save the canvas as SVG
	}
}
